CREATE TABLE IF NOT EXISTS meanings (slug TEXT PRIMARY KEY, etymology TEXT, ipa TEXT, wiktionary_gender TEXT, origin TEXT, diminutive_of TEXT);
INSERT OR REPLACE INTO meanings (slug,etymology,ipa,wiktionary_gender,origin,diminutive_of) VALUES
('james','The English New Testament form of Jacob, from Middle EnglishAPI James, from Old FrenchAPI James, from Vulgar LatinAPI Iācōmus, spoken and altered pronunciation of LatinAPI Iācōbus, from Ancient GreekAPI Ἰάκωβος (Iákōbos), from Ἰακώβ (Iakṓb), from Biblical HebrewAPI יַעֲקֹב (yaʿăqōḇ, literally “May He Heel”), from the third-person singular masculine imperfective form of the Semitic verb "to heel" (with various meanings), in turn from עָקֵב (ʿāqēḇ, “heel of the foot”). Doublet of Jacques, Jacob, Iago, Jago, Yago, Hamish, Seamus, Tiago, Santiago, and YaakovAPI. In reference to the Ecuadorian isla','/d͡ʒeɪmz/','male','Hebrew',''),
('john','From Middle EnglishAPIAPI John, Johan, Johannes, from Anglo-NormanAPI Jehan, Johan, and also Old EnglishAPI Iohannes, both from Late LatinAPI Iōhannēs, variant of LatinAPI Iōannēs, from Koine GreekAPI Ἰωάννης (Iōánnēs), from Biblical HebrewAPI יוֹחָנָן (Yôḥānān), perhaps contracted from a former יְהוֹחָנָן (Yəhōḥānān, “God is gracious”). Doublet of Jack, Jon, Johan, Johann, Johannes, Jean, Sean, Shane, Shaun, Ian, Ivan, Evan, Juan, Giovanni, and YahyaAPI.','/d͡ʒɒn/','male','the Bible < Hebrew',''),
('robert','Etymology treeProto-Indo-European &#42;kreH-der.Proto-Germanic &#42;hrōþizProto-Indo-European &#42;bʰerHǵ-Proto-Indo-European &#42;-tósProto-Indo-European &#42;bʰer(H)ǵ-tó-sProto-Germanic &#42;berhtazProto-Germanic &#42;HrōþiberhtazProto-West Germanic &#42;Hrōþiberhtder.Frankishder.Anglo-Norman Robertder.English APIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPI From Anglo-NormanAPI Robert, from the Old FrankishAPI cognate of Old High German Hrodperht (normalised form: Ruodberht), from Proto-West GermanicAPI &#42;Hrōþiberht, from Proto-GermanicAPI &#42;Hrōþiberhtaz (literally “shining glory”). Doublet of Ru','/ˈɹɑ.bɚt/','male','Germanic languages',''),
('michael','Etymology treeBiblical Hebrew מִי (mí)Biblical Hebrew כַּ־ (ka-)Proto-Semitic &#42;ʔil-Biblical Hebrew אֵל (él)Biblical Hebrew מִיכָאֵל (mīḵāʾēl)bor.Koine Greek Μῐχᾱήλ (Mĭkhāḗl)bor.Latin MichāēlOld French Michelbor.▲Latin MichāēlLatin Michāhēlbor.Old English MichahelMiddle English MichaelEnglish APIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPI From Middle EnglishAPIAPI Michael, from Old FrenchAPI Michel, Old EnglishAPI Michahel, from their source LatinAPI Michaēl, Michāhēl, from Ancient GreekAPI Μῐχᾱήλ (Mĭkhāḗl)API, from Biblical HebrewAPI מִיכָאֵל (mîḵāʾēl, literally “who is like God?”). Doub','/ˈmaɪkəl/','male','Hebrew',''),
('william','APIAPIAPI From Middle EnglishAPIAPI William, from Anglo-NormanAPI Willame, from Old High GermanAPI Willahelm, from Proto-GermanicAPI &#42;Wiljahelmaz (> Latin Gulielmus), from Proto-GermanicAPI &#42;wiljô (“will”) + &#42;helmaz (“helmet”), ultimately from the Proto-Indo-EuropeanAPI roots &#42;welh₁- (“to choose, wish, want”) and &#42;ḱel- (“to cover, conceal, save”) respectively. Cognate with Dutch Willem, German Wilhelm, etc.; cognate borrowings outside of Germanic include Guillaume and GuillermoAPI.','/ˈwɪl.i.əm/','male','Germanic languages',''),
('mary','thumb|A depiction of Mary, Mother of God, praying in quiet devotion ([[w:The Virgin in Prayer|The Virgin in Prayer by Sassoferrato, c. 1650)]] Etymology treeBiblical Hebrew מִרְיָם (miryɔm)bor.Aramaic מרים (maryam)bor.Ancient Greek Μᾰρῐ́ᾱ (Mărĭ́ā)bor.Latin MarīaOld French Mariebor.Middle English MarieEnglish APIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPI From Middle EnglishAPIAPI Marie, from Old FrenchAPI Marie, from LatinAPI Maria, from Ancient GreekAPI Μαρία (María), Μαριάμ (Mariám), from AramaicAPI מַרְיָם (maryām) or Biblical HebrewAPI מִרְיָם (miryām), of uncertain meaning (see the Hebrew entry ','/ˈmɛə.ɹi/','female','Aramaic,Hebrew',''),
('david','From Middle EnglishAPIAPI David, Davyd, Davyde, from Old EnglishAPIAPI Dauid, David, from Late LatinAPI Dāvīd, from Koine GreekAPI Δαυῑ̈́δ (Dauī̈́d), from Biblical HebrewAPI דָּוִד (dāwiḏ, literally “beloved”).','/ˈdeɪvɪd/','male','Hebrew',''),
('joseph','Etymology treeBiblical Hebrew הוֹסִיף (hosíf)der.Biblical Hebrew יוֹסֵףbor.Middle English IosephEnglish APIAPIAPIAPIAPIAPIAPIAPIAPI From Middle EnglishAPIAPI Ioseph, ultimately from Biblical HebrewAPI יוֹסֵף (Yoséf, literally “(God) shall add”); a son of Jacob. Doublet of YusufAPI. Lua error in Module:senseno at line 505: Could not find senseid, tcl, etymon, etymid template in the entry API (with language en and id &#039;one whose chastity is above temptation&#039;); this could be because you are in preview mode and the template has not yet been saved to the page is a reference to the story of','/ˈd͡ʒəʊzɪf/','male','Hebrew',''),
('richard','From Middle EnglishAPIAPI Rycharde, from Old FrenchAPI Richard, from Medieval LatinAPI Richardus, Ricohardus, from FrankishAPI &#42;Rīkahard, from Proto-GermanicAPI &#42;Rīkaharduz, a construction of &#42;rīks (“king, ruler”) +&lrm; &#42;harduz (“hard, brave”). Cognate with Old High German Rīcohard (“Richard”). Partially related to rich. A hypothetical Old English equivalent &#42;Rī‌ċheard would also yield an identical "Richard" in Modern English, though it is unknown if the Old English equivalent existed.','/ˈɹɪt͡ʃ.əd/','male','Germanic languages',''),
('charles','From FrenchAPI Charles, from Old FrenchAPI Charles, Carles, from LatinAPI Carolus, from and also reinfluenced by FrankishAPI and Old High GermanAPI Karl, from Proto-GermanicAPI &#42;karilaz (“free man”)API; compare the English word churl and the German Kerl. In reference to the Ecuadorian island, a clipping of the original name King Charles''s Island, granted in honor of Charles II of England.','/t͡ʃɑɹlz/','male','Germanic languages',''),
('thomas','Inherited from Middle EnglishAPIAPI Thomas, from LatinAPI Thōmās m (as in the Vulgate), from Ancient GreekAPI Θωμᾶς m (Thōmâs), the Biblical Greek transcription of AramaicAPI תאומא or תאמא (“twin”), the nickname of one of the Twelve Apostles. In the gospel of John (11:16, 20:24), the Aramaic nickname is also translated into Greek, as δίδυμος m (dídumos). Used as a given name since the Middle Ages, e.g. Thomas the Presbyter (7th century), Thomas the Slav (8th century), Thomas of Bayeux (died 1100). (infidel or doubter): In reference to the doubting Apostle.','/ˈtɒm.əs/','male','Aramaic',''),
('christopher','From Late LatinAPI Christophorus, from Koine GreekAPI Χρῑστόφορος (Khrīstóphoros, “carrier of Christ”), from Ancient GreekAPI Χριστός (Khristós, “Christ”) + φόρος (phóros, “carrier, bearer”), from φέρειν (phérein, “to carry, to bear”) + -ος (-os, “-er: forming agent nouns”), from the legend of Saint Christopher carrying the infant Jesus across a river.','/ˈkɹɪs.tə.fɚ/','male','Ancient Greek',''),
('daniel','From Middle EnglishAPIAPI Daniel, Daniell, from Ancient GreekAPI Δᾱνῑήλ (Dānīḗl), from HebrewAPI דָּנִיֵּאל (daniyél, literally “God is my judge”), name borne from the prophet whose story is told in the Book of Daniel.','/ˈdænjəl/','male','Hebrew',''),
('elizabeth','Etymology treeProto-Semitic &#42;ʔil-Biblical Hebrew אֵל (el)Biblical Hebrew נִשְׁבַּע (nishbá)Biblical Hebrew אֱלִישֶׁבַע (ʾĕlîšeḇaʿ)bor.Ancient Greek Ἐλισάβετ (Elisábet)der.Middle English ElizabethEnglish APIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPI From Middle EnglishAPIAPI Elizabeth, from the Ancient GreekAPI Ἐλισάβετ (Elisábet), a transliteration of the Old Testament Biblical HebrewAPI אלישבע (ʔĕlîšeḇaʕ, “my God is an oath”). See El and שבועה. Doublet of Elisheba and IsabelAPI.','/ɪˈlɪzəbəθ/','female','Hebrew',''),
('matthew','From earlier Matheu, from Old FrenchAPI Mathieu, from LatinAPI Matthaeus, from Ancient GreekAPI Ματθαῖος (Matthaîos), from AramaicAPI מַתַּי (mattay). Compare Hebrew מַתִּתְיָהוּ (mattiṯyāhū, literally “gift of the Lord”). Doublet of MattathiasAPI.','/ˈmæθjuː/','male','Hebrew',''),
('patricia','From LatinAPI patricia (“noble”)API; later also seen as the feminine form of the saint''s name Patrick.','/pəˈtɹɪʃə/','female','Latin',''),
('george','Name of an early saint, from Middle EnglishAPIAPI George, from LatinAPI Geōrgius, from Ancient GreekAPI Γεώργῐος (Geṓrgĭos), from γεωργός (geōrgós, “farmer, earth worker”), from γῆ (gê, “earth”) (combining form γεω- (geō-)) + ἔργον (érgon, “work”) Doublet of Jorge and GeevargheseAPI. The aircraft autopilot sense is probably from George DeBeeson, who patented an early (1931) autopilot system, and/or a reference to the expression let George do it. The Pullman porter sense derives from George Pullman, who hired Black people to staff his sleeping cars, and the patrons of the service seeing the Bla','/dʒɔːdʒ/','male','Ancient Greek',''),
('anthony','From LatinAPIAPI Antōnius, name of a Roman gens (with excrescent -h- suggested by an unetymological association with Ancient Greek ἄνθος (ánthos, “flower”)). The Roman clan name is of uncertain etymology, but is not Greek or Hebrew; most likely of EtruscanAPI origin, possibly derived from Ani, the Etruscan god of the sky. Doublet of AntoineAPI.','/ˈænθəni/','male','Latin',''),
('jennifer','From CornishAPI Gweniver, from Middle CornishAPI Gwynnever (cognate with Welsh Gwenhwyfar), from Proto-BrythonicAPI &#42;Gwɨnnohuɨβar. Doublet of GuinevereAPI. Compare Irish Fionnabhair, which may be cognate. The /d͡ʒ/ consonantism is due to Anglo-Norman influence; compare Old French Genievre /d͡ʒəˈniɛ̯vɾə/, /d͡ʒəˈnjɛvɾə/.','/ˈd͡ʒɛnɪfɚ/','female','Cornish',''),
('linda','Latinised short form of GermanicAPI compound names ending in -lind, -linde (“tender, soft”) (English -inda), such as Sieglinde and Dietlinde, and earlier names such as Old High German Irmilinda and Old Dutch Frithelind, from Proto-GermanicAPI &#42;linþaz (“gentle, mild”), whence also Old English līþe (“gentle, mild, pliable, limber”) (English lithe). Later misassociated with unrelated Spanish linda (“beautiful”). The name became known through 19th century literature and the opera Linda di Chamounix (1842). More at lithe. The coordination language is named after Linda LovelaceAPI, a reference t','/ˈlɪndə/','female','Germanic languages',''),
('barbara','* From LatinAPI Barbara, the name of Saint Barbara, feminine form of barbarus, from Ancient GreekAPI βάρβαρος (bárbaros, “strange, foreign”). Doublet of VarvaraAPI. * (logic): From the given name; chosen because it has three A''s in it representing universal affirmatives.','/ˈbɑɹb(ə)ɹə/','female','Latin',''),
('donald','APIAPI Name of Scottish kings and an early saint, from Scottish GaelicAPIAPI Dòmhnall and reinforced by Medieval LatinAPI Donvaldus ~ Donaldus, from Old IrishAPI Domnall, from Proto-CelticAPI &#42;Dubnowalos (“prince / chief of the world”). Doublet of DomhnallAPI.','/ˈdɒn.əld/','male','Scottish Gaelic',''),
('paul','From LatinAPI PaulusAPI, from paulus (“small”). Doublet of Pablo and PaoloAPI.','/pɔːl/','male','Latin',''),
('mark','From Middle EnglishAPIAPI Mark, from the LatinAPI praenomen (i.e. first name) Mārcus, derived from Mārs, the Roman god of war, originally Māvors, from Proto-ItalicAPI &#42;Māwortis.','/maːk/','male','Latin',''),
('andrew','Etymology treeProto-Indo-European &#42;h₂nḗrProto-Graeco-Phrygian &#42;anḗrProto-Hellenic &#42;anḗrAncient Greek ᾱ̆̓νήρ (ā̆nḗr)Ancient Greek Ἀνδρέᾱς (Andréās)der.English APIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPI From Ancient GreekAPI Ἀνδρέας (Andréas), cognate with ἀνδρεῖος (andreîos, “manly”), both from ἀνήρ (anḗr, “man”). Doublet of André, Andreas, Andrei, and AndreyAPI.','/ˈæn.dɹuː/','male','Ancient Greek',''),
('edward','Etymology treeProto-Germanic &#42;audazProto-Indo-European &#42;wer-Proto-Indo-European &#42;wor-túsProto-Germanic &#42;warduzProto-Germanic &#42;AudawarduzProto-West Germanic &#42;AudawarduOld English ĒadweardMiddle English EdwardEnglish APIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPIAPI From Middle EnglishAPIAPI Edward, from Old EnglishAPIAPI Ēadweard, from Proto-West GermanicAPIAPI &#42;Audawardu, from Proto-GermanicAPIAPI &#42;Audawarduz, corresponding to ed (“wealth, riches”) + ward (“ward, guard”), doublet of EduardAPI.','/ˈɛdwəd/','male','Old English',''),
('steven','APIAPI Inherited from Middle EnglishAPIAPI Stevene, Steven, from Anglo-NormanAPI Estievne, Estievene, from LatinAPI Stephanus, from Ancient GreekAPI Στέφανος (Stéphanos), from στέφανος (stéphanos, “crown, wreath”), from στέφω (stéphō, “to put round, to surround”).','/ˈstiːvən/','male','Ancient Greek',''),
('kenneth','Anglicized form of two GoidelicAPI names, Old IrishAPI Cináed, the name of Scottish kings derived from PictishAPI &#42;ᚉᚔᚅᚔᚑᚇ (Ciniod), and the saint''s name Cainnech (literally “handsome”) (modern Scottish Gaelic Coinneach), as in the surname Mackenzie.','/ˈkɛn.əθ/','male','Scottish Gaelic',''),
('margaret','From the name of 3rd century Saint Margaret the Virgin, from Middle EnglishAPIAPI Margaret, from Old FrenchAPI Margaret (French Marguerite), from LatinAPI Margarita, from Ancient GreekAPI μαργαρίτης (margarítēs, “pearl”), ultimately from an Indo-Iranian source. The same source, through folk etymology, has produced Old English meregrot (“pearl”, literally “stone or pebble of the sea”), related to Old Saxon merigrita, merigriota (“pearl”), Old High German merigrioz, equivalent to mer- +&lrm; groat.','/ˈmɑːɡɹɪt/','female','Ancient Greek',''),
('joshua','From Biblical HebrewAPI יְהוֹשֻׁעַ (Yehoshúa''), perhaps from הוֹשֵׁעַ (Hoshéa'') with addition of יהוה (YHWH, “Yahweh”), thus meaning "Yahweh is salvation". See הוֹשִׁיעַ (hoshía'', “to save”). By cognate a direct equivalent to Jesus via Latin Iēsūs and Ancient Greek Ἰησοῦς (Iēsoûs) from Aramaic יֵשׁוּע (Yēšū́ʿ), akin to Hebrew יֵשׁוּעַ (Yeshúa''), a variant of Yehoshúa''. The Greek Septuagint translation of the Hebrew Bible and the Greek New Testament consistently render the two Hebrew names Yehoshúa'' (whence Joshua) and Yeshúa'' (whence Jeshua) into Koine Greek as Iēsoûs (whence Jesus).','/ˈd͡ʒɒʃ(j)ʊə/','male','Hebrew',''),
('kevin','APIAPI Name of a seventh-century Irish saint, from IrishAPI Caoimhghin or Caoimhín, from Old IrishAPI Cóemgen (literally “dear birth/person”). It first became popular outside Ireland in the mid-twentieth century.','/ˈkɛvɪn/','male','Irish',''),
('brian','Borrowed from IrishAPIAPI Brian. Doublet of BrendanAPI.','/ˈbɹaɪ.ən/','male','Irish',''),
('susan','English form of the biblical Susanna, from Biblical Hebrew שׁוֹשַׁנָּה (šōšannā, “lily”), ultimately from EgyptianAPI z:S:n-M9 (zšn).','/ˈsuː.zən/','female','Hebrew',''),
('dorothy','','/ˈdɒɹ.ə.θi/','female','Ancient Greek',''),
('sarah','From Biblical HebrewAPIAPI שָׂרָה (śārâ, “lady, princess”), from the Biblical figure originally named Sarai (שָׂרָי (śārāy, literally “masters, princes”)).','/ˈsɛɚ.ə/','female','Hebrew',''),
('timothy','From Middle FrenchAPI Timothée, from LatinAPI Tīmotheus, from Ancient GreekAPI Τῑμόθεος (Tīmótheos), from τῑμάω (tīmáō, “to honour”) + θεός (theós, “god”).','/ˈtɪməθi/','male','Ancient Greek',''),
('ronald','Anglicized from Scottish GaelicAPIAPI Raghnall, itself derived from Old NorseAPI Rǫgnvaldr, from rǫgn (“advice”) + valdr (“power”), later partly merged with the Continental Germanic equivalent Reynold.','/ˈɹɒ.nəld/','male','Germanic languages',''),
('jason','From the Ancient GreekAPI Ἰάσων (Iásōn), from ἰάομαι (iáomai, “I heal”). The Jason mentioned in the New Testament (Acts 17:5-9, Romans 16:21) is probably a Greek rendering of Joshua.','/ˈdʒeɪsən/','male','Ancient Greek',''),
('jessica','First used by William Shakespeare in Merchant of Venice in the early 17th century, probably from HebrewAPI יִסְכָּה (yiská, “Iscah in Genesis 11:29, Jescha in the Wycliffe version”), a proper name meaning "he will see/behold/look for", the 3ms imperfect form of a verb ultimately from the root ס־כ־ה (s-k-h), itself an alternative form of the root שׂ־כ־ה (ś-k-h), both of which mean "to see, behold, look for". * By folk etymology seen as an elaborate form of Jessie, from Jane.','/ˈd͡ʒɛsɪkə/','female','Hebrew',''),
('helen','From FrenchAPI Hélène, from LatinAPI Helena, from Ancient GreekAPI Ἑλένη (Helénē). Doublet of ElaineAPI.','/ˈhɛlən/','female','Ancient Greek',''),
('nancy','Medieval diminutive of Ann and Agnes. Compare Betsy, Patsy.','/ˈnænsi/','female','',''),
('betty','','/ˈbɛti/','female','',''),
('ryan','','/ˈɹaɪən/','','',''),
('karen','From DanishAPIAPI Karen, a vernacular form of Catherine that arose in medieval Denmark. The sense "middle-aged woman" comes from the popularity of the name among baby boomers and Gen-Xers. The derogatory usage was popularized via African-American Vernacular English.','/ˈkæɹən/','female','Danish',''),
('jacob','From Middle EnglishAPIAPI Iacob, from Late LatinAPI Iācōbus, from Ancient GreekAPI Ἰάκωβος (Iákōbos), from Biblical HebrewAPI יַעֲקֹב (yaʿăqōḇ, literally “May He Heel”), from the third-person singular masculine imperfective form of the Semitic verb "to heel" (with various meanings), in turn from עָקֵב (ʿāqēḇ, “heel of the foot”). Doublet of James, Yaakov, and YakubAPI.','/ˈd͡ʒeɪkəb/','male','Hebrew',''),
('jeffrey','Variant of Geoffrey.','/ˈd͡ʒɛfɹi/','male','Germanic languages',''),
('lisa','Diminutive of Elisabeth in several European languages. The computer is named after Lisa Brennan-Jobs, officially explained as an acronym for “Locally Integrated Software Architecture”.','/ˈliːsə/','female','Hebrew',''),
('nicholas','From Middle EnglishAPI Nicholas, from Old FrenchAPI Nicholas, from LatinAPI Nīcolāus, from Ancient GreekAPI Νικόλαος (Nikólaos), from νίκη (níkē, “victory”) +&lrm; λαός (laós, “people”).','/ˈnɪk.ə.ləs/','male','Ancient Greek',''),
('frank','From Middle EnglishAPIAPI Frank, partially from Old EnglishAPIAPI Franca (“a Frank”); and partially from Old FrenchAPI Franc, and/or LatinAPI Francus (“a Frank”), from FrankishAPI &#42;Franko (“a Frank”); both maybe from Proto-GermanicAPI &#42;frankô (“javelin”). Cognate with Old High German Franko (“a Frank”), Old English franca (“spear, javelin”). Compare Saxon, ultimately a derivative of Proto-Germanic &#42;sahsą (“knife, dagger”). Doublet of franc, frank, and farangAPI.','/ˈfɹæŋk/','male','Germanic languages',''),
('anna','From Late LatinAPI Anna both directly and via numerous other languages, chiefly in reference to St Anne the apocryphal mother of Mary mother of Jesus but appearing in the Vulgate in reference to Anne the Prophetess, from Koine GreekAPI Ἄννα (Ánna) in the New Testament, from HebrewAPI חַנָּה (Ḥannâ, “Hannah”), from חַנָּה (ḥannâ, “grace, gracious, graced with child”). As a city in Illinois, named for Anna Davie, wife of one of the initial settlers. Doublet of Ann, Anne, Ana, and HannahAPI.','/ˈænə/','female','Latin',''),
('gary','Medieval short form of GermanicAPI compound names beginning with gari or geri ("spear"), such as Gerard, Garrett, Gerald, or Gerbert. Cognate with the Scottish and Irish name Garaidh. Sometimes also a short form of Gareth. The popularity of the given name in the 20th century is due to the American actor Gary Cooper, whose stage name was invented by his agent, a native of Gary, Indiana.','/ˈɡæɹ.ɪ/','male','Germanic languages',''),
('emily','English form of LatinAPI AemiliaAPI, a gens name from aemulus (“rival, emulator”).','','female','Latin',''),
('eric','From Middle EnglishAPIAPI Eric, from Old EnglishAPIAPI Eoric, from Old NorseAPI Eirríkr, Eiríkr (from ei (“always, eternal”, see aye) +&lrm; ríkr (“ruler”)), or from Proto-GermanicAPI &#42;Aizarīkijaz (from &#42;aizō (“honor”) +&lrm; &#42;rīkijaz (“ruler”)). Less likely from einn (“sole, alone”) +&lrm; ríkr (“ruler”), from Proto-GermanicAPI &#42;rīks (“king”, cognate to Latin rēx and Gaulish &#42;rīx). The name was in use in Anglo-Saxon Britain, reinforced by Scandinavian settlers before the Norman Conquest. Compare Danish Erik, German Erich. Possible doublet of EuricAPI.','/ˈɛɹɪk/','male','Germanic languages',''),
('sandra','A short form of Alexandra and, less often, of Cassandra.','/ˈsandɹə/','female','',''),
('ashley','From Old EnglishAPIAPI &#42;Æsċlēah, composed of æsċ (“ash tree”) + lēah (“wood, clearing”). Equivalent to Ash +&lrm; -leyAPI.','/ˈæʃli/','male','surnames',''),
('jonathan','Borrowed from HebrewAPIAPI יְהוֹנָתָן (yəhōnāṯān), יוֹנָתָן (yōnāṯān, literally “God has given”), apparently with influence from Aramaic [Term?]API.','/ˈd͡ʒɒnəθən/','male','Hebrew',''),
('stephen','APIAPI From LatinAPI Stephanus, from Ancient GreekAPI Στέφανος (Stéphanos), from στέφανος (stéphanos, “crown, wreath”), from στέφω (stéphō, “to put round, to surround”). From &#42;stegʷʰ- (“to enlace”) + -νος (-nos, suffix forming an adjective or noun) from Proto-Indo-EuropeanAPI &#42;-nós (suffix forming a verbal adjective from a verb stem).','/ˈstiːvən/','male','Ancient Greek',''),
('kimberly','Variant spelling of Kimberley.','','','surnames',''),
('ruth','From Ruth the Moabite, HebrewAPI רות, of uncertain origin, possibly meaning "companion". Also associated with the English noun ruth (“compassion”) by Puritans.','/ɹuːθ/','female','Hebrew',''),
('donna','A 19th-century invention from the ItalianAPI noun donna; also interpreted as a feminine form of Donald.','/ˈdɒnə/','female','Italian','');